package org.usbworkbench;
import java.io.*;import java.util.*;
public class ReadMapTest {
 static int checks;static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}
 static class Disk implements BlockDevice {long blocks=16384,bad=-1;int writes,reads;public int blockSize(){return 512;}public long blockCount(){return blocks;}public void read(long at,byte[] b,int n)throws IOException{reads++;if(at<0||n%512!=0||n/512>blocks-at)throw new IOException("BOUNDS");if(bad>=at&&bad<at+n/512)throw new IOException("OWNED_READ_FAILURE");Arrays.fill(b,0,n,(byte)0);}public void write(long at,byte[] b,int n){writes++;throw new AssertionError("drive must never be written");}public void sync(){}public void close(){}}
 static void error(String code,Throwing f)throws Exception{try{f.run();throw new AssertionError("Expected "+code);}catch(IOException e){check(e.getMessage().equals(code),e.toString());}}interface Throwing{void run()throws Exception;}
 public static void main(String[] args)throws Exception{Disk d=new Disk();byte[] id=ReadMap.identity(d,"OWNED:1");ReadMap.State s=ReadMap.fresh(d,id);final byte[][] checkpoint={null};ReadMap.Save save=m->checkpoint[0]=m.encode();ReadMap.scan(d,s,id,(a,b)->{},()->false,save);check(s.complete()&&s.good==d.blocks&&s.errors.isEmpty(),"complete good map");check(d.writes==0,"no writes");ReadMap.State loaded=ReadMap.decode(new ByteArrayInputStream(checkpoint[0]));check(loaded.next==d.blocks&&Arrays.equals(loaded.identity,id),"checksummed checkpoint");check(ReadMap.report(loaded).startsWith("READ_MAP\n1\n"),"report");
 s=ReadMap.fresh(d,id);final boolean[] cancel={false};final ReadMap.State canceled=s;error("CANCELLED",()->ReadMap.scan(d,canceled,id,(a,b)->cancel[0]=true,()->cancel[0],save));check(canceled.next==2048&&canceled.good==2048,"cancel saves exact cursor");loaded=ReadMap.decode(new ByteArrayInputStream(checkpoint[0]));ReadMap.scan(d,loaded,id,(a,b)->{},()->false,save);check(loaded.complete(),"resume canceled scan");
 d.bad=2500;s=ReadMap.fresh(d,id);final ReadMap.State broken=s;error("READ_MAP_PAUSED",()->ReadMap.scan(d,broken,id,(a,b)->{},()->false,save));check(broken.next==4096&&broken.good==2048&&broken.errors.size()==1,"failed range saved and scan stops");check(broken.errors.get(0).start==2048&&broken.errors.get(0).count==2048,"failed request range not sector defect claim");loaded=ReadMap.decode(new ByteArrayInputStream(checkpoint[0]));ReadMap.scan(d,loaded,id,(a,b)->{},()->false,save);check(loaded.complete()&&loaded.good==d.blocks-2048,"resume AFTER failed request");check(d.writes==0,"resume still read only");
 final ReadMap.State done=loaded;byte[] wrong=id.clone();wrong[0]^=1;int reads=d.reads;error("READ_MAP_IDENTITY",()->ReadMap.scan(d,done,wrong,(a,b)->{},()->false,save));check(d.reads==reads,"wrong identity refused before reads");
 byte[] bad=checkpoint[0].clone();bad[8]^=1;error("READ_MAP_RECORD",()->ReadMap.decode(new ByteArrayInputStream(bad)));error("READ_MAP_RECORD",()->ReadMap.decode(new ByteArrayInputStream(new byte[99])));error("READ_MAP_RECORD",()->ReadMap.decode(new ByteArrayInputStream(new byte[65637])));
 d.bad=-1;ReadMap.State large=ReadMap.fresh(d,id);for(int i=0;i<4096;i++)large.errors.add(new ReadMap.Range(i,1));large.next=4096;error("READ_MAP_LIMIT",()->ReadMap.scan(d,large,id,(a,b)->{},()->false,save));check(ReadMap.decode(new ByteArrayInputStream(checkpoint[0])).errors.size()==4096,"bounded max ranges retained");check(checkpoint[0].length==65636,"bounded private record size");
 d.blocks=1;s=ReadMap.fresh(d,id);ReadMap.scan(d,s,id,(a,b)->{},()->false,save);check(s.complete()&&s.good==1,"partial last chunk/small device");
 d.blocks=4294967297L;error("READ_MAP_OPTIONS",()->ReadMap.identity(d,"OWNED"));check(d.writes==0,"all cases zero drive writes");
 String en=ReportText.render(ReadMap.report(done),false),ar=ReportText.render(ReadMap.report(done),true);check(en.contains("Recorded failed")&&!en.matches("(?s).*[\\u0600-\\u06ff].*"),"English map report");check(ar.contains("طلبات القراءة الفاشلة")&&!ar.contains("Scanned"),"Arabic map report");System.out.println("PASS: "+checks+" read-map checkpoint/error/cancel/resume/identity/geometry/bounds/selected-language/no-write checks");}
}
